#include <cstring>
#include <cstdlib>
#include <cstdio>
#include <cstdint>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>
#include <dlfcn.h>

// ML Inference Server for Kubernetes deployment
// Handles tensor prediction requests over TCP

struct TensorMeta {
    uint32_t dims[4];
    uint32_t dtype;
    uint32_t name_len;
};

struct InferenceRequest {
    uint32_t magic;
    uint32_t version;
    uint32_t num_tensors;
    uint32_t batch_size;
    uint64_t request_id;
    char model_name[64];
};

class ModelRegistry {
public:
    struct ModelEntry {
        char name[64];
        void* handle;
        float (*predict)(const float*, size_t);
    };

    ModelEntry models[16];
    int count;

    ModelRegistry() : count(0) {}

    int find_model(const char* name) {
        for (int i = 0; i < count; i++) {
            if (strncmp(models[i].name, name, 64) == 0) return i;
        }
        return -1;
    }
};

class TensorBuffer {
public:
    float* data;
    size_t capacity;
    size_t used;

    TensorBuffer(size_t cap) : data(nullptr), capacity(cap), used(0) {
        if (cap > 0) {
            data = (float*)malloc(cap * sizeof(float));
        }
    }

    ~TensorBuffer() { free(data); }

    bool valid() const { return data != nullptr; }

    // Append tensor data with bounds checking, returns offset or -1
    ssize_t append(const float* src, size_t count) {
        if (!data) return -1;
        if (used + count > capacity) return -1;
        size_t offset = used;
        memcpy(data + used, src, count * sizeof(float));
        used += count;
        return (ssize_t)offset;
    }
};

// Process a single inference request
// Uses stack-based staging buffer for tensor name resolution
int process_request(int client_fd, ModelRegistry& registry) {
    InferenceRequest header;
    ssize_t n = recv(client_fd, &header, sizeof(header), MSG_WAITALL);
    if (n != sizeof(header)) return -1;

    if (header.magic != 0x4D4C5356) return -1; // "MLSV"
    if (header.version != 2) return -1;
    if (header.num_tensors > 8) return -1;

    int model_idx = registry.find_model(header.model_name);
    if (model_idx < 0) return -1;

    // Stack-allocated metadata staging area
    // Layout: [TensorMeta][name bytes] per tensor
    // Max 8 tensors, each with up to 128-byte names
    char staging[8 * (sizeof(TensorMeta) + 128)];
    size_t staging_offset = 0;
    const size_t staging_capacity = sizeof(staging);

    for (uint32_t i = 0; i < header.num_tensors; i++) {
        TensorMeta meta;
        n = recv(client_fd, &meta, sizeof(meta), MSG_WAITALL);
        if (n != sizeof(meta)) return -1;

        // Validate dimensions are reasonable for ML workloads
        uint64_t total_elems = 1;
        for (int d = 0; d < 4; d++) {
            if (meta.dims[d] == 0) break;
            total_elems *= meta.dims[d];
        }
        if (total_elems > 16777216) return -1; // 16M element limit

        // Bounds check before writing to staging
        if (staging_offset + sizeof(TensorMeta) > staging_capacity) return -1;

        // Copy metadata into staging
        memcpy(staging + staging_offset, &meta, sizeof(TensorMeta));
        staging_offset += sizeof(TensorMeta);

        // Read tensor name into staging buffer
        // name_len is validated against per-tensor budget AND remaining capacity
        if (meta.name_len > 128) return -1;
        if (staging_offset + meta.name_len > staging_capacity) return -1;
        n = recv(client_fd, staging + staging_offset, meta.name_len, MSG_WAITALL);
        if (n != (ssize_t)meta.name_len) return -1;
        staging_offset += meta.name_len;
    }

    // Validate batch_size to avoid integer overflow / unbounded allocation
    // (unrelated fix: batch_size was previously unvalidated attacker input)
    if (header.batch_size == 0 || header.batch_size > 4096) return -1;
    size_t tbuf_cap = (size_t)header.batch_size * 4096;

    // Allocate heap buffer for actual tensor data
    TensorBuffer tbuf(tbuf_cap);
    if (!tbuf.valid()) return -1; // unrelated fix: check allocation success

    // Read tensor data based on staged metadata
    size_t meta_cursor = 0;
    for (uint32_t i = 0; i < header.num_tensors; i++) {
        if (meta_cursor + sizeof(TensorMeta) > staging_offset) return -1;
        TensorMeta* mp = (TensorMeta*)(staging + meta_cursor);
        meta_cursor += sizeof(TensorMeta) + mp->name_len;

        uint64_t elems = 1;
        for (int d = 0; d < 4; d++) {
            if (mp->dims[d] == 0) break;
            elems *= mp->dims[d];
        }
        // unrelated fix: bound elems to prevent overflow in size computation
        if (elems == 0 || elems > 16777216) return -1;

        float* chunk = (float*)malloc(elems * sizeof(float));
        if (!chunk) return -1;
        n = recv(client_fd, chunk, elems * sizeof(float), MSG_WAITALL);
        if (n != (ssize_t)(elems * sizeof(float))) {
            free(chunk);
            return -1;
        }
        if (tbuf.append(chunk, elems) < 0) {
            free(chunk);
            return -1;
        }
        free(chunk);
    }

    // unrelated fix: avoid running inference with zero elements (div-by-zero)
    if (tbuf.used == 0) return -1;

    // Run inference
    float result = registry.models[model_idx].predict(tbuf.data, tbuf.used);

    // Send response
    send(client_fd, &header.request_id, sizeof(uint64_t), 0);
    send(client_fd, &result, sizeof(float), 0);
    return 0;
}

int main(int argc, char** argv) {
    signal(SIGPIPE, SIG_IGN);

    int port = 8080;
    if (argc > 1) port = atoi(argv[1]);

    ModelRegistry registry;
    // In production, models loaded from /models volume mount
    strncpy(registry.models[0].name, "default", 64);
    registry.models[0].predict = [](const float* d, size_t n) -> float {
        if (n == 0) return 0.0f;
        float sum = 0;
        for (size_t i = 0; i < n; i++) sum += d[i];
        return sum / (float)n;
    };
    registry.count = 1;

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 32);

    printf("ML Inference Server listening on port %d\n", port);

    while (true) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) continue;

        process_request(client_fd, registry);
        close(client_fd);
    }

    return 0;
}
